mapper.select:
        select  t.rel_id,t.rel_id relId,t.pg_id,t.pg_id pgId,t.p_id,t.p_id pId,t.status_cd,t.status_cd statusCd,t.level_cd,t.level_cd levelCd 
from p_privilege_rel t 
where 1 =1 

   and t.rel_id= #{relId}


   and t.pg_id= #{pgId}


   and t.p_id= #{pId}


   and t.status_cd= #{statusCd}


   and t.level_cd= #{levelCd}

order by t.create_time desc

   limit #{page}, #{row}

mapper.update:
